<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import PrimaryButton from '@/Components/PrimaryButton.vue'; import {Head,Link,useForm} from '@inertiajs/vue3';
interface Department{id:number;name:string} interface ExternalOrganization{id:number;name:string} interface ExternalDepartment{id:number;external_organization_id:number;name:string}
interface Letter{id:number;type:'incoming'|'outgoing'|'internal';classification:'ordinary'|'confidential';subject:string;letter_number:string|null;sender_name:string|null;recipient_name:string|null;received_at:string|null;sent_at:string|null;recipient_department_id:number|null;external_organization_id:number|null;external_department_id:number|null}
const props=defineProps<{correspondence:Letter;departments:Department[];externalOrganizations:ExternalOrganization[];externalDepartments:ExternalDepartment[]}>();
const form=useForm({subject:props.correspondence.subject,classification:props.correspondence.classification,letter_number:props.correspondence.letter_number??'',sender_name:props.correspondence.sender_name??'',recipient_name:props.correspondence.recipient_name??'',received_at:props.correspondence.received_at??'',sent_at:props.correspondence.sent_at??'',recipient_department_id:props.correspondence.recipient_department_id?String(props.correspondence.recipient_department_id):'',external_organization_id:props.correspondence.external_organization_id?String(props.correspondence.external_organization_id):'',external_department_id:props.correspondence.external_department_id?String(props.correspondence.external_department_id):''});
const externalDepartments=()=>props.externalDepartments.filter(d=>String(d.external_organization_id)===form.external_organization_id);
function submit():void{form.put(route('correspondence.update',props.correspondence.id))}
</script>
<template><Head title="ویرایش مکاتبه"/><AuthenticatedLayout><template #header><div><h2 class="text-xl font-bold text-slate-900">ویرایش مکاتبه</h2><p class="mt-1 text-sm text-slate-500">ویرایش فقط پیش از ثبت هر اقدام گردش و توسط دبیرخانه مجاز است.</p></div></template>
<div class="mx-auto max-w-4xl p-4 sm:p-6" dir="rtl"><form class="space-y-5 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm" @submit.prevent="submit">
<div><label for="subject" class="mb-2 block text-sm font-semibold">موضوع *</label><input id="subject" v-model="form.subject" required maxlength="255" class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.subject"/></div>
<div v-if="correspondence.type==='incoming'"><label for="letter_number" class="mb-2 block text-sm font-semibold">شماره نامه روی اصل نامه *</label><input id="letter_number" v-model="form.letter_number" required maxlength="100" class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.letter_number"/></div>
<div class="grid gap-4 sm:grid-cols-2">
<div><label for="classification" class="mb-2 block text-sm font-semibold">طبقه‌بندی</label><select id="classification" v-model="form.classification" class="w-full rounded-xl border-slate-300 text-sm"><option value="ordinary">عادی</option><option value="confidential">محرمانه</option></select><InputError :message="form.errors.classification"/></div>
<div v-if="correspondence.type==='incoming'||correspondence.type==='internal'"><label for="recipient_department_id" class="mb-2 block text-sm font-semibold">واحد دریافت‌کننده *</label><select id="recipient_department_id" v-model="form.recipient_department_id" required class="w-full rounded-xl border-slate-300 text-sm"><option value="">انتخاب واحد</option><option v-for="d in departments" :key="d.id" :value="String(d.id)">{{d.name}}</option></select><InputError :message="form.errors.recipient_department_id"/></div>
<div v-if="correspondence.type==='incoming'"><label for="sender_name" class="mb-2 block text-sm font-semibold">فرستنده</label><input id="sender_name" v-model="form.sender_name" class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.sender_name"/></div>
<div v-if="correspondence.type==='outgoing'"><label for="recipient_name" class="mb-2 block text-sm font-semibold">گیرنده</label><input id="recipient_name" v-model="form.recipient_name" class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.recipient_name"/></div>
<div v-if="correspondence.type==='incoming'"><label for="received_at" class="mb-2 block text-sm font-semibold">تاریخ دریافت *</label><input id="received_at" v-model="form.received_at" type="date" required class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.received_at"/></div>
<div v-if="correspondence.type==='outgoing'"><label for="sent_at" class="mb-2 block text-sm font-semibold">تاریخ ارسال *</label><input id="sent_at" v-model="form.sent_at" type="date" required class="w-full rounded-xl border-slate-300 text-sm"/><InputError :message="form.errors.sent_at"/></div>
<div><label for="external_organization_id" class="mb-2 block text-sm font-semibold">{{props.correspondence.type === "incoming" ? "سازمان مبدأ نامه" : "سازمان مخاطب"}}<span v-if="['incoming', 'outgoing'].includes(props.correspondence.type)" class="text-rose-600"> *</span></label><select id="external_organization_id" v-model="form.external_organization_id" :required="['incoming', 'outgoing'].includes(props.correspondence.type)" class="w-full rounded-xl border-slate-300 text-sm"><option value="">انتخاب نشده</option><option v-for="o in externalOrganizations" :key="o.id" :value="String(o.id)">{{o.name}}</option></select><InputError :message="form.errors.external_organization_id"/></div>
<div><label for="external_department_id" class="mb-2 block text-sm font-semibold">واحد بیرونی</label><select id="external_department_id" v-model="form.external_department_id" class="w-full rounded-xl border-slate-300 text-sm"><option value="">انتخاب نشده</option><option v-for="d in externalDepartments()" :key="d.id" :value="String(d.id)">{{d.name}}</option></select><InputError :message="form.errors.external_department_id"/></div>
</div><div class="flex items-center justify-between border-t pt-4"><Link :href="route('correspondence.index')" class="text-sm font-semibold">انصراف</Link><PrimaryButton :disabled="form.processing">{{form.processing?'در حال ذخیره...':'ذخیره تغییرات'}}</PrimaryButton></div></form></div></AuthenticatedLayout></template>